/// <summary>
/// Extension of TAMRebateDeal form
/// </summary>
[ExtensionOf(formStr(TAMRebateDeal))]
internal final class METTAMRebateDealFrm_Extension
{   
}

Method.Source:
/// <summary>
/// Bug 293485: CB201- Transaction type field is non editable when creating a new deal, until we reload the webpage for finops
/// Moving/refactoring from METTAMRebateDeal_TAMRebateTable_Extension\active to here 
/// </summary>
public void enableFields()
{
    void fieldAllowEdit(FormDataSource _fds, FieldId _fieldId, boolean _allowEdit)
    {
        _fds.object(_fieldId).allowEdit(_allowEdit);
        _fds.object(_fieldId).skip(!_allowEdit);
    }

    next enableFields();

    boolean allowEditTierLineTypeValue = !TAMRebateDeal.METVolumetricTierDeal 
                                      || (TAMRebateDeal.METVolumetricTierDeal && TAMRebateTable.METTierLineType == METTierLineType::Value);

    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, METAvgBy454Week), allowEditTierLineTypeValue);        

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, UnitId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, MinimumAmount), allowEditTierLineTypeValue);

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, Category), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, RebatePostingId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, GuaranteePostingId), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, DocumentNotes), allowEditTierLineTypeValue);

    // Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
    // so that we can item item distribution method for volumetric tier deals
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeTax), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeCreditNote), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeDiscountedAmount), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, PaidInvoices), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeFreeText), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, IncludeSettlementDiscount), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, SupportNegativeTier), allowEditTierLineTypeValue);

    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebatePer), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebatePeriodCode), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebateClaimPer), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, RebateClaimBy), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateDate_ds, fieldNum(TAMRebateDate, ProcessPosting), allowEditTierLineTypeValue);

    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, RebateBasis), allowEditTierLineTypeValue);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, CalculationMethod), allowEditTierLineTypeValue);

    // Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    // Transaction type not editable when use external sales data
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, SourceType), !TAMRebateDeal.METUseExternalSellData);

    // Moved from TAMRebateDealGUPExtensionHelper_Post_setUpGUPUIForRebateDealFormDetailPage
    fieldAllowEdit(TAMRebateDeal_ds, fieldNum(TAMRebateDeal, RebateOutputType), !TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, AccountCode), false);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, AccountRelation), false);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, ItemCode), false);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, ItemRelation), false);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, VariantId), false);

    // moved from METTAMRebateDealEventHandler\InventDim_OnActivated
    fieldAllowEdit(InventDim_ds, fieldNum(InventDim, configId), false);
    fieldAllowEdit(InventDim_ds, fieldNum(InventDim, InventSizeId), false);
    fieldAllowEdit(InventDim_ds, fieldNum(InventDim, InventColorId), false);

    // moved from METTAMRebateDealEventHandler\TAMRebateDeal_OnActivated
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).mandatory(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METInvoiceConsolidationByRebateType)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    FormDataObject vendRebateTypeIdFdo = TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METVendRebateTypeId));
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, METVendRebateTypeId), TAMRebateDeal.METInvoiceConsolidationByRebateType);
    vendRebateTypeIdFdo.mandatory(TAMRebateDeal.METInvoiceConsolidationByRebateType);
    vendRebateTypeIdFdo.visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    fieldAllowEdit(TAMRebateDeal_ds, fieldNum(TAMRebateDeal, METVolumetricTierDeal), TAMRebateDeal.ModuleInventCustVend != ModuleInventCustVend::Vend);
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVolumetricTierDeal)).visible(TAMRebateDeal.ModuleInventCustVend != ModuleInventCustVend::Vend);

    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METTierLineType)).visible(TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateDeal_ds, fieldNum(TAMRebateDeal, RebateOutputType), TAMRebateDeal.METVolumetricTierDeal);
    fieldAllowEdit(TAMRebateDeal_ds, fieldNum(TAMRebateDeal, RebateTypeGUP), TAMRebateDeal.METVolumetricTierDeal);

    // moved from METTAMRebateDealFrm_Extension\init
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METExternalRebateDealReference)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceComponentCode)).visible(false);
    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METPriceAttributeGroupCombination)).visible(false);
    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METHeaderPriceAttributeGroup)).visible(false);      
    this.design().controlName(formControlStr(TAMRebateDeal, METHeaderPriceAttributeGroupDetail)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METLinePriceAttributeGroup)).visible(false);
    this.design().controlName(formControlStr(TAMRebateDeal, METLinePriceAttributeGroupDetail)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    // Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
    // Field not to editable and not mandatory for Vendor rebate deals on purchase order basis and External data rebate deals.
    boolean isSalesOrder = TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust
        || (TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
        && TAMRebateTable.RebateBasisVend == TAMRebateBasisVend::Sales)
        && !TAMRebateDeal.METUseExternalSellData;

    TAMRebateTable_ds.object(fieldNum(TAMRebateTable, METItemDistributionMethod)).mandatory(isSalesOrder);
    fieldAllowEdit(TAMRebateTable_ds, fieldNum(TAMRebateTable, METItemDistributionMethod), isSalesOrder);

    //CB201 - Field can be edited only when the rebate deal is not active
    fieldAllowEdit(TAMRebateDeal_ds, fieldNum(TAMRebateDeal, METApplyCustomAggregation), !TAMRebateDeal.RebateActive);
}

/// <summary>
/// Bug 293485: CB201- Transaction type field is non editable when creating a new deal, until we reload the webpage for finops
/// Moving/refactoring buttons logic from METTAMRebateDeal_TAMRebateTable_Extension\active to here
/// </summary>
public void enableButtons()
{       
    next enableButtons();

    boolean allowEditTierLineTypeRate = !TAMRebateDeal.METVolumetricTierDeal
                                     || (TAMRebateDeal.METVolumetricTierDeal && TAMRebateTable.METTierLineType == METTierLineType::Rate);

    AddLine.enabled(allowEditTierLineTypeRate);
    RemoveLine.enabled(allowEditTierLineTypeRate);

    // moved from METTAMRebateDealEventHandler\TAMRebateDeal_OnActivated
    METTierRateTrans.enabled(TAMRebateDeal.METVolumetricTierDeal && TAMRebateDeal.State == TAMRebateDealWorkflowState::Completed);
    METTierRateCalculationController.enabled(TAMRebateDeal.METVolumetricTierDeal && TAMRebateDeal.State == TAMRebateDealWorkflowState::Completed);
    GUPRebatePartialWriteOff.visible(!TAMRebateDeal.METVolumetricTierDeal);
    TAMRebateCreateTransWriteOff.visible(!TAMRebateDeal.METVolumetricTierDeal);
    TAMRebatePostWriteOff.visible(!TAMRebateDeal.METVolumetricTierDeal);
    PostRebatePartial.visible(!TAMRebateDeal.METVolumetricTierDeal);
}
